import{_ as o,o as l,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Asok Gems and How To Polish Them - Marcel Lauhoff, Clyso","description":"","frontmatter":{"title":"Asok Gems and How To Polish Them - Marcel Lauhoff, Clyso","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Admin Socket","工具开发","数据可视化","Ceph 运维"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Asok_Gems_and_How_To_Polish_Them_-_Marcel_Lauhoff_Clyso.md","filePath":"posts/2025/Asok_Gems_and_How_To_Polish_Them_-_Marcel_Lauhoff_Clyso.md","lastUpdated":1780459816000}'),d={name:"posts/2025/Asok_Gems_and_How_To_Polish_Them_-_Marcel_Lauhoff_Clyso.md"};function t(c,e,s,r,_,n){return l(),i("div",null,[...e[0]||(e[0]=[a('<p>本次会议主要围绕 Ceph Admin Socket 的功能、应用及工具开发展开，深入探讨了如何利用 Admin Socket 获取集群内部信息、探索未文档化命令，以及如何通过工具优化数据可视化和管理效率。</p><h4 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h4><ol><li><p><strong>Admin Socket 简介</strong></p><ul><li>Ceph Admin Socket 是一种通过 Unix Socket 文件与 Ceph 守护进程（如 OSD、MON、MDS、RGW）交互的接口，支持查询状态、配置和性能指标。</li><li>访问方式包括原生工具 <code>ceph daemon</code>、<code>ceph tell</code> 和 <code>librados</code>，以及通过 <code>netcat</code> + JSON 直接与 Socket 通信。</li><li>开发者可以轻松添加自定义命令。</li></ul></li><li><p><strong>Admin Socket 命令生态</strong></p><ul><li>目前共 179 个命令，分布在 OSD、MDS 等服务中，另有 25 个通用命令。</li><li>近半数命令未在官方文档中提及，但可通过 <code>help</code> 查看功能说明。</li><li>高频实用命令包括 <code>dump_historic_ops</code>、<code>counter dump</code>、<code>config diff</code> 等。</li></ul></li><li><p><strong>工具开发与数据可视化</strong></p><ul><li>配置管理工具如 <code>config diff</code> 可用于解析和可视化配置差异。</li><li>网络诊断工具如 <code>messenger dump</code> 可用于获取 TCP 连接状态和性能指标。</li><li>性能分析工具如 <code>dump_historic_ops</code> 可用于展示操作耗时分布。</li></ul></li><li><p><strong>未来计划</strong></p><ul><li>工具生态扩展，开发 TUI 工具、Ceph 插件等。</li><li>标准化 Admin Socket 命令，提升工具兼容性。</li><li>社区协作，鼓励贡献更多工具。</li></ul></li></ol><h4 id="关键决定" tabindex="-1">关键决定 <a class="header-anchor" href="#关键决定" aria-label="Permalink to &quot;关键决定&quot;">​</a></h4><ul><li>优先探索未文档化命令。</li><li>推广工具开发范式，基于 JSON 输出 + <code>jq</code>/Python 快速构建诊断工具。</li><li>整合监控能力，将 <code>messenger dump</code> 和 <code>counter dump</code> 数据接入 Prometheus/Grafana。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完善 <code>CN-top</code> 功能。</li><li>提交 <code>config diff</code> 可视化工具到 Ceph 生态库。</li><li>调研 <code>dump_historic_ops</code> 的图表化方案。</li><li>组织 Admin Socket 命令文档补全计划。</li></ul><h4 id="问答环节亮点" tabindex="-1">问答环节亮点 <a class="header-anchor" href="#问答环节亮点" aria-label="Permalink to &quot;问答环节亮点&quot;">​</a></h4><ul><li>Admin Socket 查询可能轻微影响性能。</li><li>未来计划将 Admin Socket 数据纳入自动化分析工具链。</li><li>RBD Mirror 专用命令需补充到现有命令统计中。</li></ul><p>本次会议强调了 Admin Socket 在 Ceph 运维中的重要性，并鼓励社区开发和利用相关的工具，以提升 Ceph 集群的管理效率和性能。</p>',10)])])}const m=o(d,[["render",t]]);export{p as __pageData,m as default};
